import{_ as t,o,c as d,a5 as a}from"./chunks/framework.BMR-TWOq.js";const m=JSON.parse('{"title":"Sport Client — Python Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/python/sport-client.md","filePath":"software/sdk/python/sport-client.md","lastUpdated":1794576042000}'),s={name:"software/sdk/python/sport-client.md"};function n(c,e,i,r,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="sport-client-—-python-example" tabindex="-1">Sport Client — Python Example <a class="header-anchor" href="#sport-client-—-python-example" aria-label="Permalink to &quot;Sport Client — Python Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/python/example/sport/rbq_sport_client.py</code></p><p>Python port of the C++ <a href="/RBQ/nightly/software/sdk/cpp/sport-client.html"><code>rbq_sport_client</code></a>.<br> An interactive terminal application that sends <strong>SportClient</strong> commands to the robot one at a time — one request per line you enter.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The program has a single main loop that:</p><ol><li>Reads a line of input from <code>stdin</code> (<code>list</code>, a command name, or a command ID).</li><li>Updates the active <code>TestOption</code>.</li><li>Calls the matching <code>SportClient</code> method once, then waits for the next line.</li></ol><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><code>rbq_sdk_py</code> installed — see <a href="/RBQ/nightly/software/sdk/python/overview.html">Python SDK Overview</a>.</li><li>Robot stack running (simulation or hardware) and reachable on the chosen network interface.</li></ul><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>From <code>rbq_sdk/python/example/sport/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_sport_client.py</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [networkInterface]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Simulator / on-robot stack — interface defaults to lo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_sport_client.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Real robot — pass the interface that reaches it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_sport_client.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span></code></pre></div><h2 id="available-commands" tabindex="-1">Available commands <a class="header-anchor" href="#available-commands" aria-label="Permalink to &quot;Available commands&quot;">​</a></h2><p>Type <code>list</code> at the prompt to print all commands.</p><table tabindex="0"><thead><tr><th>ID</th><th>Name</th><th>SportClient method called</th></tr></thead><tbody><tr><td>0</td><td><code>damp</code></td><td><code>Damp()</code></td></tr><tr><td>1</td><td><code>balance_stand</code></td><td><code>BalanceStand()</code></td></tr><tr><td>2</td><td><code>stop_move</code></td><td><code>StopMove()</code></td></tr><tr><td>3</td><td><code>stand_down</code></td><td><code>StandDown()</code></td></tr><tr><td>4</td><td><code>recovery_stand</code></td><td><code>RecoveryStand()</code></td></tr><tr><td>5</td><td><code>move</code></td><td><code>Move(0.0, 0.0, 0.5)</code> — rotate in place</td></tr><tr><td>6</td><td><code>switch_gait</code></td><td><code>SwitchGait(0)</code> — switch to the walk gait (<code>49</code>)</td></tr><tr><td>7</td><td><code>speed_level</code></td><td><code>SpeedLevel(1)</code> — fast: <code>move</code> speeds × 1.5</td></tr><tr><td>8</td><td><code>get_state</code></td><td><code>GetState()</code> — print the robot state</td></tr><tr><td>9</td><td><code>body_height</code></td><td><code>BodyHeight(-0.1)</code> — body 10 cm lower</td></tr><tr><td>10</td><td><code>stand_up</code></td><td><code>StandUp()</code></td></tr><tr><td>11</td><td><code>enter_leftside_gait</code></td><td><code>LeftSideGait(1)</code></td></tr><tr><td>12</td><td><code>exit_leftside_gait</code></td><td><code>LeftSideGait(0)</code> — back to the walk gait (<code>49</code>)</td></tr><tr><td>13</td><td><code>enter_handstand</code></td><td><code>HandStand(1)</code> — switch to the <code>RL_FRONT_WALK</code> (31) policy</td></tr><tr><td>14</td><td><code>exit_handstand</code></td><td><code>HandStand(0)</code> — back to the walk gait (<code>49</code>)</td></tr><tr><td>15</td><td><code>pose</code></td><td><code>BodyPosition(0.0, 0.0, -0.1, 0.2)</code> — body 10 cm lower, turned 0.2 rad</td></tr><tr><td>16</td><td><code>euler</code></td><td><code>Euler(0.2, 0.3, 0.3)</code> — tilt the body (roll, pitch, yaw in radians)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Test IDs 11–14 in an open area — the C++ example source marks them &quot;Caution: test in open area&quot;.</p></div><blockquote><p>Every command except <code>move</code> waits for the robot&#39;s answer and prints its code. <code>move</code> does not wait and prints <code>0</code>.</p></blockquote><blockquote><p><code>move</code>, <code>body_height</code>, <code>pose</code> and <code>euler</code> act only when control mode is HighLevel. The example turns it on at start by publishing <code>true</code> on <code>rt/rbq/cmd/switch_control_mode</code> (ROS <a href="/RBQ/nightly/software/sdk/ros/topics.html#rbq-cmd-switch-control-mode"><code>/rbq/cmd/switch_control_mode</code></a>); moving the gamepad stick turns it off again. While it is off the robot answers <code>3205</code> (rejected) instead of <code>0</code>. <code>Move()</code> does not wait for that answer and returns <code>0</code>; <code>LastMoveCode()</code> returns the robot&#39;s answer to the latest <code>Move()</code>. <code>move</code> also needs a walking gait — run <code>switch_gait</code> (6) before <code>move</code>.</p></blockquote><blockquote><p><code>switch_gait</code> sets the walk gait <code>49</code>. <code>SwitchGait(1)</code> (running) sets the same gait — <code>49</code> takes its fast policy above 1.3 m/s on its own. <code>SwitchGait(2)</code> (climb) sets the vision walk <code>48</code>, which uses the robot&#39;s vision for the terrain; without vision it keeps walking without terrain input and gives no warning. Leaving the left-side gait or the handstand goes back to <code>49</code>.</p></blockquote><blockquote><p><code>Euler(roll, pitch, yaw)</code> takes radians. <code>BodyHeight(h)</code> and the <code>z</code> of <code>BodyPosition(x, y, z, yaw)</code> are metres from the default height; its <code>yaw</code> is radians. Standing (gait <code>1</code>), the robot follows roll ±25°, pitch ±20°, yaw ±25° and height −0.15 to +0.05 m. Walking (<code>48</code>, <code>49</code>), it follows only pitch (±25°) and height (−0.25 to +0.1 m). Larger values are clipped. The pose stays while you <code>move</code> or <code>stop_move</code> and goes back to level on <code>stand_up</code>, <code>stand_down</code>, <code>balance_stand</code>, <code>recovery_stand</code> and <code>damp</code>. If the robot sits, falls or is stopped another way (the app, an e-stop), the SDK drops the pose and the next <code>move</code> or <code>stop_move</code> levels the body — a robot stood up again in HighLevel mode before that may keep the last pose. The robot cannot shift its body forward or sideways, so <code>BodyPosition</code> returns <code>3204</code> (parameter error) unless <code>x</code> and <code>y</code> are <code>0</code>.</p></blockquote><blockquote><p><code>SpeedLevel(-1)</code> is slow, <code>0</code> normal (the default) and <code>1</code> fast: the robot multiplies <code>move</code> speeds by 0.5, 1 or 1.5. The gait&#39;s own speed limit still applies. The level goes back to <code>0</code> when the robot software restarts.</p></blockquote><blockquote><p><code>get_state</code> prints the robot&#39;s answer, one key per line:</p></blockquote><table tabindex="0"><thead><tr><th>Key</th><th>Value</th></tr></thead><tbody><tr><td><code>fsm_id</code></td><td>Current gait ID (<a href="/RBQ/nightly/software/sdk/ros/reference.html#gait-state-ids">Gait State IDs</a>)</td></tr><tr><td><code>fsm_name</code></td><td>Current gait name</td></tr><tr><td><code>speed_level</code></td><td><code>-1</code>, <code>0</code> or <code>1</code></td></tr><tr><td><code>control_mode</code></td><td><code>1</code> HighLevel, <code>0</code> joystick</td></tr><tr><td><code>is_standing</code></td><td><code>1</code> or <code>0</code></td></tr><tr><td><code>is_fall</code></td><td><code>1</code> or <code>0</code></td></tr></tbody></table><h2 id="usage-example" tabindex="-1">Usage example <a class="header-anchor" href="#usage-example" aria-label="Permalink to &quot;Usage example&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ python3 rbq_sport_client.py eth0</span></span>
<span class="line"><span>Input &quot;list &quot; to list all test option ...</span></span>
<span class="line"><span>balance_stand</span></span>
<span class="line"><span>Test: balance_stand, test_id: 1</span></span>
<span class="line"><span>Request successed: balance_stand, code: 0</span></span>
<span class="line"><span>move</span></span>
<span class="line"><span>Test: move, test_id: 5</span></span>
<span class="line"><span>Request successed: move, code: 0</span></span></code></pre></div><h2 id="key-implementation-notes" tabindex="-1">Key implementation notes <a class="header-anchor" href="#key-implementation-notes" aria-label="Permalink to &quot;Key implementation notes&quot;">​</a></h2><ul><li><strong><code>SetTimeout(25.0)</code></strong>: The Python <code>SportClient</code> sets a 25-second timeout — relevant for RPC-style calls like <code>GetState</code>.</li><li><strong>One request per line</strong>: <code>input()</code> blocks until you press Enter, so the loop sends one request per line — it does not repeat the command.</li><li><strong><code>get_state</code></strong>: Prints every key of the robot&#39;s answer.</li></ul><h2 id="differences-from-the-c-version" tabindex="-1">Differences from the C++ version <a class="header-anchor" href="#differences-from-the-c-version" aria-label="Permalink to &quot;Differences from the C++ version&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>C++</th><th>Python</th></tr></thead><tbody><tr><td>Timeout</td><td>default</td><td><code>SetTimeout(25.0)</code> set explicitly</td></tr><tr><td><code>ConvertToInt</code> on failure</td><td>returns <code>-1</code></td><td>returns <code>None</code> (no false match on ID 0)</td></tr><tr><td>Terminal input</td><td><code>std::getline</code> blocking</td><td><code>input()</code> blocking</td></tr><tr><td>Error message</td><td>prints count</td><td>prints count</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/software/sdk/python/sport-client-joy.html">Sport Client Joystick (Python)</a></li><li><a href="/RBQ/nightly/software/sdk/cpp/sport-client.html">Sport Client (C++)</a></li><li><a href="/RBQ/nightly/software/sdk/python/overview.html">Python SDK Overview</a></li></ul>`,30)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
